import itertools
sheet = 'W1::Allowed assignments'
rows = data_rows(sheet, {'L': 'string', 'M': 'string', 'N': 'number'}, 812, 820)
tasks = list(set(cell(sheet, f'L{r}') for r in rows))
workers = list(set(cell(sheet, f'M{r}') for r in rows))
cost_map = {(cell(sheet, f'L{r}'), cell(sheet, f'M{r}')): num(sheet, f'N{r}') for r in rows}
max_tasks = 0
for p in itertools.permutations(workers, len(tasks)):
    valid = True
    for t, w in zip(tasks, p):
        if (t, w) not in cost_map:
            valid = False
            break
    if valid:
        max_tasks = max(max_tasks, len(tasks))
result = max_tasks

